-- 1. DELETE: Xóa có điều kiện, ghi log đầy đủ, giữ lại cấu trúc và High Water Mark
BEGIN;
DELETE FROM audit_logs WHERE created_at < NOW() - INTERVAL '30 days';
-- Có thể ROLLBACK nếu phát hiện xóa nhầm
ROLLBACK;

-- 2. TRUNCATE: Dọn sạch siêu tốc hàng chục triệu dòng, reset ID
-- Trong PostgreSQL, TRUNCATE vẫn an toàn trong transaction:
BEGIN;
TRUNCATE TABLE staging_events RESTART IDENTITY;
COMMIT;

-- 3. DROP: Xóa sổ hoàn toàn bảng khỏi cơ sở dữ liệu
DROP TABLE IF EXISTS old_backup_users CASCADE;

