-- Thiết kế minh họa cả 4 loại khóa trong kiến trúc phân quyền
CREATE TABLE users (
    user_id SERIAL PRIMARY KEY,              -- 1. PRIMARY KEY: Duy nhất, NOT NULL
    email VARCHAR(255) NOT NULL UNIQUE,      -- 2. UNIQUE KEY: Không được trùng lặp
    id_card_number VARCHAR(20) NULL UNIQUE   -- UNIQUE cho phép giá trị NULL nếu chưa cập nhật
);

CREATE TABLE roles (
    role_id SERIAL PRIMARY KEY,
    role_name VARCHAR(50) NOT NULL UNIQUE
);

-- Bảng nối gán quyền người dùng
CREATE TABLE user_roles (
    user_id INT NOT NULL,
    role_id INT NOT NULL,
    granted_at TIMESTAMPTZ DEFAULT NOW(),

    -- 3. COMPOSITE PRIMARY KEY: Tổ hợp 2 cột tạo thành khóa chính duy nhất
    PRIMARY KEY (user_id, role_id),

    -- 4. FOREIGN KEYS: Ràng buộc tham chiếu tới bảng cha
    CONSTRAINT fk_ur_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_ur_role FOREIGN KEY (role_id) REFERENCES roles(role_id) ON DELETE CASCADE
);

-- BẮT BUỘC: Tự tạo Index cho Foreign Key role_id (user_id đã được index bởi PK)
CREATE INDEX idx_user_roles_role_id ON user_roles(role_id);

