-- 1. QUAN HỆ 1 - 1: Users và UserProfiles (FK + UNIQUE)
CREATE TABLE users (
    user_id SERIAL PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE user_profiles (
    profile_id SERIAL PRIMARY KEY,
    user_id INT NOT NULL UNIQUE, -- UNIQUE ép buộc quan hệ 1 - 1 tuyệt đối
    id_card VARCHAR(20) NOT NULL,
    CONSTRAINT fk_profile_user FOREIGN KEY (user_id) REFERENCES users(user_id)
);

-- 2. QUAN HỆ 1 - N: Classes và Students (FK nằm ở bảng Students)
CREATE TABLE classes (
    class_id SERIAL PRIMARY KEY,
    class_name VARCHAR(50) NOT NULL
);

CREATE TABLE students (
    student_id SERIAL PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    class_id INT NOT NULL, -- FK phía Nhiều trỏ về Một
    CONSTRAINT fk_student_class FOREIGN KEY (class_id) REFERENCES classes(class_id)
);

-- 3. QUAN HỆ N - N: Students và Courses (Thông qua Bảng nối Enrollments)
CREATE TABLE courses (
    course_id SERIAL PRIMARY KEY,
    course_name VARCHAR(100) NOT NULL
);

-- BẢNG NỐI (Junction Table)
CREATE TABLE enrollments (
    student_id INT NOT NULL,
    course_id INT NOT NULL,
    enrolled_at TIMESTAMPTZ DEFAULT NOW(),
    final_grade NUMERIC(4, 2) NULL, -- Thuộc tính riêng của mối quan hệ
    PRIMARY KEY (student_id, course_id),
    CONSTRAINT fk_enr_student FOREIGN KEY (student_id) REFERENCES students(student_id),
    CONSTRAINT fk_enr_course FOREIGN KEY (course_id) REFERENCES courses(course_id)
);

