-- Minh họa chuyển đổi Isolation Level trong PostgreSQL / MySQL

-- 1. Thiết lập mức cô lập cho toàn bộ Transaction hiện tại
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;

-- Transaction này được đảm bảo: Dù các transaction khác có UPDATE và COMMIT bao nhiêu lần,
-- thì câu lệnh SELECT này vẫn luôn luôn trả về cùng một kết quả duy nhất (Consistent Snapshot)
SELECT SUM(balance) FROM bank_accounts;

-- Giả sử bên ngoài có transaction khác nạp thêm tiền và COMMIT...

-- Đọc lại lần 2: Vẫn ra chính xác con số như lần 1 (Chặn Non-repeatable Read)
SELECT SUM(balance) FROM bank_accounts;

COMMIT;

