-- So sánh 2 cách tiếp cận hàng đầu trong PostgreSQL

-- CÁCH 1: VARCHAR + CHECK Constraint (Khuyên dùng: Cân bằng hoàn hảo giữa an toàn và dễ bảo trì)
CREATE TABLE orders_recommended (
    order_id BIGSERIAL PRIMARY KEY,
    status VARCHAR(30) NOT NULL DEFAULT 'PENDING',
    CONSTRAINT chk_order_status CHECK (
        status IN ('PENDING', 'PAID', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED', 'REFUNDED')
    )
);

-- Khi cần thêm trạng thái mới 'ON_HOLD' trong tương lai: Siêu nhanh, không lock bảng!
-- ALTER TABLE orders_recommended DROP CONSTRAINT chk_order_status;
-- ALTER TABLE orders_recommended ADD CONSTRAINT chk_order_status CHECK (status IN (...));

---------------------------------------------------------------------------------
-- CÁCH 2: Lookup Table (Phù hợp khi trạng thái có metadata phong phú cho UI/Báo cáo)
CREATE TABLE order_statuses (
    status_code VARCHAR(30) PRIMARY KEY, -- 'PAID', 'SHIPPED'
    display_name_vi VARCHAR(100) NOT NULL,
    ui_badge_color VARCHAR(20) NOT NULL,
    can_cancel BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE orders_enterprise (
    order_id BIGSERIAL PRIMARY KEY,
    status_code VARCHAR(30) NOT NULL REFERENCES order_statuses(status_code)
);

