// Hàm tính toán Redis TTL chuẩn sản xuất kết hợp Jitter (TypeScript/Node.js)
import Redis from 'ioredis';
const redis = new Redis();

/**
 * Lưu cache an toàn với TTL Jitter ngẫu nhiên
 * @param key Khóa cache
 * @param value Dữ liệu cần lưu
 * @param baseTtlSeconds Thời gian sống cơ bản (giây)
 * @param jitterPercent Tỷ lệ phần trăm dao động ngẫu nhiên (mặc định 15%)
 */
export async function setCacheWithJitter(
  key: string,
  value: any,
  baseTtlSeconds: number,
  jitterPercent: number = 0.15
): Promise<void> {
  // Tính toán khoảng dao động: Ví dụ 3600s với 15% -> dao động tối đa 540s
  const maxJitter = Math.floor(baseTtlSeconds * jitterPercent);
  // Sinh số ngẫu nhiên từ -maxJitter đến +maxJitter
  const randomOffset = Math.floor(Math.random() * (2 * maxJitter + 1)) - maxJitter;

  const effectiveTtl = Math.max(1, baseTtlSeconds + randomOffset);
  const payload = JSON.stringify(value);

  // Lưu vào Redis với TTL đã được phân tán ngẫu nhiên
  await redis.set(key, payload, 'EX', effectiveTtl);
}

