// Thiết kế Cache Key Service chuẩn mực với Versioning và Invalidation an toàn
import Redis from 'ioredis';
const redis = new Redis();

export class CacheKeyManager {
  private static readonly SERVICE_PREFIX = 'shop';
  private static readonly USER_SCHEMA_VERSION = 'v2'; // Nâng lên v3 khi đổi schema dữ liệu

  // Sinh key có cấu trúc rõ ràng: shop:user:v2:105
  static getUserKey(userId: string | number): string {
    return `${this.SERVICE_PREFIX}:user:${this.USER_SCHEMA_VERSION}:${userId}`;
  }

  // Xóa danh sách keys theo pattern AN TOÀN bằng SCAN và UNLINK (Không bao giờ dùng KEYS)
  static async safeDeletePattern(pattern: string): Promise<number> {
    let cursor = '0';
    let totalDeleted = 0;

    do {
      // Quét từng batch 100 keys để không block event loop của Redis
      const [nextCursor, keys] = await redis.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
      cursor = nextCursor;

      if (keys.length > 0) {
        // Dùng UNLINK thay vì DEL để giải phóng RAM bất đồng bộ (Non-blocking)
        await redis.unlink(...keys);
        totalDeleted += keys.length;
      }
    } while (cursor !== '0');

    return totalDeleted;
  }
}

