// Minh họa: Header điều khiển Browser & CDN Cache cho Static/Dynamic content trên Express

// 1. Tài nguyên tĩnh (JS, CSS, Ảnh đại diện có mã hash): Cache 1 năm trên Browser & CDN
app.use('/static', express.static('public', {
  maxAge: '1y',
  immutable: true // Báo cho trình duyệt không bao giờ cần kiểm tra lại
}));

// 2. API Công khai ít đổi (Top 10 bài viết xem nhiều): Cache 5 phút trên CDN Edge
app.get('/api/v1/articles/trending', (req, res) => {
  // s-maxage dành cho CDN (Shared Cache), max-age dành cho Browser
  res.setHeader('Cache-Control', 'public, max-age=60, s-maxage=300, stale-while-revalidate=60');
  return res.json(getTrendingArticles());
});

// 3. API Cá nhân nhạy cảm (Số dư, Profile cá nhân): TUYỆT ĐỐI KHÔNG ĐỂ CDN CACHE
app.get('/api/v1/user/profile', authMiddleware, (req, res) => {
  res.setHeader('Cache-Control', 'private, no-cache, no-store, must-revalidate');
  return res.json(req.userProfile);
});

