-- Sức mạnh vượt trội của PostgreSQL: Khả năng mở rộng kiểu dữ liệu phức tạp
-- 1. Lưu trữ và đánh index nhị phân trên JSONB siêu tốc
CREATE TABLE event_logs (
    event_id BIGSERIAL PRIMARY KEY,
    payload JSONB NOT NULL
);
CREATE INDEX idx_logs_user_id ON event_logs USING gin ((payload -> 'user_id'));

-- 2. Tích hợp AI Vector Search trực tiếp bằng extension pgvector
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE document_embeddings (
    doc_id BIGSERIAL PRIMARY KEY,
    content TEXT,
    embedding vector(1536) -- Vector 1536 chiều từ OpenAI text-embedding-3-small
);

-- Tìm kiếm 5 tài liệu tương đồng ngữ nghĩa nhất bằng Cosine Distance (<=>)
SELECT doc_id, content, 1 - (embedding <=> '[0.012, -0.023, ...]') AS similarity
FROM document_embeddings
ORDER BY embedding <=> '[0.012, -0.023, ...]'
LIMIT 5;

