-- Tìm kiếm 5 tài liệu tương đồng ngữ nghĩa nhất bằng Cosine Distance (<=>)
SELECT doc_id, content, 1 - (embedding <=> '[0.012, -0.023, ...]') AS similarity
FROM document_embeddings
ORDER BY embedding <=> '[0.012, -0.023, ...]'
LIMIT 5;

