-- Ánh xạ DDL vật lý tương ứng từ sơ đồ ERD trên
CREATE TABLE customers (
    customer_id BIGSERIAL PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL
);

CREATE TABLE orders (
    order_id BIGSERIAL PRIMARY KEY,
    customer_id BIGINT NOT NULL REFERENCES customers(customer_id),
    order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    grand_total DECIMAL(12, 2) NOT NULL
);

CREATE TABLE order_items (
    item_id BIGSERIAL PRIMARY KEY,
    order_id BIGINT NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
    product_id BIGINT NOT NULL,
    quantity INT NOT NULL CHECK (quantity > 0),
    unit_price DECIMAL(12, 2) NOT NULL
);

-- 1. Chiến lược truyền thống: BIGINT Auto-increment (Tối ưu cho Monolith & B-tree)
CREATE TABLE orders_auto_inc (
    id BIGSERIAL PRIMARY KEY, -- 8 bytes, ghi tuần tự cực nhanh
    public_tracking_code VARCHAR(32) NOT NULL UNIQUE -- Mã lộ ra ngoài cho khách
);

-- 2. Chiến lược hiện đại: Sử dụng UUIDv7 có thứ tự thời gian (PostgreSQL 17+ hoặc qua hàm)
-- Ưu điểm: Phân tán, không đoán được, nhưng ghi tuần tự O(1) không phân mảnh B-tree!
CREATE TABLE orders_uuidv7 (
    -- Trong PostgreSQL, kiểu UUID chỉ tốn 16 bytes nhị phân
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(), -- Khuyến nghị dùng UUIDv7 function
    customer_id UUID NOT NULL,
    total_amount NUMERIC(12, 2) NOT NULL
);

