// Các loại Index chuyên dụng trong MongoDB

// 1. Compound Index tuân thủ quy tắc vàng ESR (Equality -> Sort -> Range)
db.orders.createIndex({ 
  customer_id: 1,  // 1. Equality
  created_at: -1,  // 2. Sort
  total_amount: 1  // 3. Range
});

// 2. Multikey Index: Đánh index trên mảng tags
// Khi mảng tags: ["nodejs", "mongodb"], Mongo tự tạo 2 entry index độc lập
db.articles.createIndex({ tags: 1 });

// 3. TTL Index: Tự động xóa OTP sau đúng 300 giây (5 phút)
db.otp_codes.createIndex(
  { created_at: 1 }, 
  { expireAfterSeconds: 300 }
);

// 4. Geospatial 2dsphere Index: Tìm tài xế xung quanh tọa độ GPS
db.drivers.createIndex({ location: "2dsphere" });
// Query: db.drivers.find({ location: { $near: { $geometry: { type: "Point", coordinates: [106.66, 10.76] }, $maxDistance: 5000 } } });

// 5. Wildcard Index: Đánh index cho trường metadata có cấu trúc tùy biến linh hoạt
db.products.createIndex({ "custom_attributes.$**": 1 });

