-- Minh họa sử dụng SAVEPOINT để xử lý Rollback từng phần an toàn
BEGIN; -- Bắt đầu giao dịch lớn (Xử lý đơn hàng)

-- Bước 1: Trừ tiền khách hàng (Bắt buộc thành công)
UPDATE user_wallets SET balance = balance - 100000 WHERE user_id = 101;

-- Bước 2: Tạo Savepoint trước khi thực hiện tác vụ phụ (Cộng điểm thưởng)
SAVEPOINT loyalty_points_step;

-- Thử cộng điểm thưởng
INSERT INTO loyalty_points (user_id, points) VALUES (101, 50);

-- Giả sử phát hiện logic điểm thưởng bị lỗi, ta chỉ ROLLBACK tác vụ cộng điểm:
ROLLBACK TO SAVEPOINT loyalty_points_step;
-- Dòng INSERT điểm bị hủy bỏ, nhưng lệnh UPDATE trừ tiền ví ở Bước 1 VẪN ĐƯỢC BẢO TOÀN!

-- Giải phóng savepoint sau khi xử lý xong
RELEASE SAVEPOINT loyalty_points_step;

-- Bước 3: Hoàn tất đơn hàng và Commit toàn bộ
INSERT INTO orders (user_id, total_amount) VALUES (101, 100000);
COMMIT;

