// Minh họa: Chiến lược Hybrid kết hợp giữa ORM và Raw SQL trong TypeScript (Prisma)
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

// 1. Tác vụ CRUD hàng ngày: Tận dụng 100% sức mạnh Type-Safe của ORM
export async function createNewUser(email: string, name: string) {
  return await prisma.user.create({
    data: { email, name }
  });
}

// 2. Tác vụ thống kê báo cáo phức tạp: Thoát ly ORM, dùng Raw SQL tối ưu tuyệt đối
export async function getMonthlyRevenueReport(year: number) {
  // Dùng $queryRaw để tận dụng Window Functions và CTEs mà ORM không thể sinh tối ưu
  return await prisma.$queryRaw<Array<{ month: number; revenue: number; growth_rate: number }>>`
    WITH monthly_sales AS (
      SELECT 
        EXTRACT(MONTH FROM created_at)::INT AS month,
        SUM(grand_total) AS revenue
      FROM orders
      WHERE EXTRACT(YEAR FROM created_at) = ${year} AND status = 'COMPLETED'
      GROUP BY month
    )
    SELECT 
      month,
      revenue,
      ROUND(
        ((revenue - LAG(revenue) OVER (ORDER BY month)) / NULLIF(LAG(revenue) OVER (ORDER BY month), 0)) * 100, 
        2
      ) AS growth_rate
    FROM monthly_sales
    ORDER BY month ASC;
  `;
}

