// Sử dụng Prisma Client với Type-Safety tuyệt đối trong TypeScript
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

async function handleOrderCreation(userId: string, variantId: string, quantity: number) {
  // Prisma hỗ trợ Interactive Transactions cực kỳ trực quan
  return await prisma.$transaction(async (tx) => {
    // 1. Trừ tồn kho có điều kiện (Atomic Check)
    const updatedVariant = await tx.productVariant.update({
      where: { id: variantId, stockQuantity: { gte: quantity } },
      data: { stockQuantity: { decrement: quantity } }
    });

    // 2. Tạo đơn hàng và chi tiết đơn hàng trong cùng transaction
    const order = await tx.order.create({
      data: {
        userId,
        status: 'PAID',
        items: {
          create: {
            variantId: updatedVariant.id,
            quantity: quantity,
            price: updatedVariant.price
          }
        }
      },
      // Tự động type-safe trả về cả dữ liệu quan hệ items
      include: {
        items: true
      }
    });

    return order;
  });
}

