// Định nghĩa Schema Mongoose chuẩn với Hooks và Tối ưu hóa .lean()
import mongoose, { Schema, Document } from 'mongoose';
import bcrypt from 'bcrypt';

const UserSchema = new Schema({
  email: { type: String, required: true, unique: true, lowercase: true, trim: true },
  password: { type: String, required: true, select: false }, // select: false chống lộ hash khi query
  firstName: { type: String, required: true },
  lastName: { type: String, required: true }
}, {
  timestamps: true // Tự động quản lý createdAt và updatedAt
});

// 1. Virtual Property: Không lưu vào DB, chỉ sinh ra khi đọc
UserSchema.virtual('fullName').get(function() {
  return `${this.firstName} ${this.lastName}`;
});

// 2. Middleware Hook: Tự động băm mật khẩu trước khi lưu vào MongoDB
UserSchema.pre('save', async function(next) {
  if (!this.isModified('password')) return next();
  this.password = await bcrypt.hash(this.password, 12);
  next();
});

export const UserModel = mongoose.model('User', UserSchema);

// 3. 🚀 TỐI ƯU HIỆU NĂNG: Dùng .lean() cho các truy vấn chỉ đọc
export async function getTopUsers() {
  return await UserModel.find().limit(100).lean(); // Trả về Plain JS Object siêu nhẹ!
}

