import { pgTable, serial, text, timestamp, integer } from 'drizzle-orm/pg-core';
import { drizzle } from 'drizzle-orm/node-postgres';
import { eq, desc } from 'drizzle-orm';
import { Pool } from 'pg';

// 1. Định nghĩa Schema bằng code TypeScript (Không cần file schema riêng)
export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  fullName: text('full_name').notNull(),
  email: text('email').notNull().unique(),
  createdAt: timestamp('created_at').defaultNow().notNull()
});

export const posts = pgTable('posts', {
  id: serial('id').primaryKey(),
  title: text('title').notNull(),
  authorId: integer('author_id').references(() => users.id),
  createdAt: timestamp('created_at').defaultNow().notNull()
});

const db = drizzle(new Pool());

// 2. Truy vấn theo phong cách SQL-like: Trong sáng, không có overhead ma thuật
export async function getRecentUserPosts(userId: number) {
  return await db.select({
    postId: posts.id,
    title: posts.title,
    author: users.fullName
  })
  .from(posts)
  .innerJoin(users, eq(posts.authorId, users.id))
  .where(eq(users.id, userId))
  .orderBy(desc(posts.createdAt))
  .limit(10);
}

