// Triển khai mẫu Cache-Aside Pattern chuẩn mực với Redis và ioredis
import Redis from 'ioredis';
import { db } from './database';

const redis = new Redis(process.env.REDIS_URL!);
const CACHE_TTL_SECONDS = 300; // 5 phút

export async function getProductDetails(productId: string) {
  const cacheKey = `cache:product:${productId}`;

  // 1. Đọc từ Redis Cache trước (Độ trễ < 1ms)
  const cachedData = await redis.get(cacheKey);
  if (cachedData) {
    return JSON.parse(cachedData); // Cache Hit!
  }

  // 2. Cache Miss: Truy vấn Database chính
  const product = await db.product.findUnique({
    where: { id: productId },
    include: { category: true }
  });

  if (!product) return null;

  // 3. Tái tạo cache bất đồng bộ với TTL Jitter ngẫu nhiên
  const jitter = Math.floor(Math.random() * 30);
  await redis.set(cacheKey, JSON.stringify(product), 'EX', CACHE_TTL_SECONDS + jitter);

  return product;
}

