db.orders.aggregate([
  // Giai đoạn 1: $match ĐẶT ĐẦU TIÊN để dùng Index lọc đơn hàng tháng 3 (Tương đương WHERE)
  {
    $match: {
      status: "COMPLETED",
      order_date: { 
        $gte: ISODate("2024-03-01T00:00:00Z"), 
        $lt: ISODate("2024-04-01T00:00:00Z") 
      }
    }
  },

  // Giai đoạn 2: $unwind để bóc tách từng món hàng trong mảng items
  { $unwind: "$items" },

  // Giai đoạn 3: $group theo category_id và tính tổng doanh thu
  {
    $group: {
      _id: "$items.category_id",
      totalRevenue: { $sum: { $multiply: ["$items.price", "$items.quantity"] } },
      totalQuantitySold: { $sum: "$items.quantity" }
    }
  },

  // Giai đoạn 4: $lookup để JOIN sang collection 'categories' lấy tên danh mục
  {
    $lookup: {
      from: "categories",
      localField: "_id",
      foreignField: "_id",
      as: "categoryDetails"
    }
  },

  // Giai đoạn 5: $unwind kết quả categoryDetails
  { $unwind: "$categoryDetails" },

  // Giai đoạn 6: $project định dạng lại kết quả đầu ra sạch đẹp
