// Ứng dụng thực tế các kiểu dữ liệu Redis bằng ioredis (Node.js)
import Redis from 'ioredis';
const redis = new Redis();

async function demonstrateRedisDataStructures() {
  // 1. STRINGS: Bộ đếm nguyên tử & Rate Limiting
  await redis.incr('article:105:views'); // Tăng view siêu tốc O(1)

  // 2. HASHES: Lưu thông tin người dùng (Đọc/ghi từng trường độc lập)
  await redis.hset('user:101', { name: 'Hoàng Nam', role: 'ADMIN' });
  const role = await redis.hget('user:101', 'role'); // Chỉ lấy 1 trường, tiết kiệm RAM

  // 3. LISTS: Hàng đợi công việc (Message Queue)
  await redis.lpush('task_queue', JSON.stringify({ taskId: 1, type: 'SEND_EMAIL' }));
  const nextTask = await redis.rpop('task_queue'); // FIFO Queue

  // 4. SETS: Tag bài viết và Tìm bạn chung (Set Intersection)
  await redis.sadd('user:101:friends', 'user:201', 'user:202', 'user:203');
  await redis.sadd('user:102:friends', 'user:202', 'user:203', 'user:204');
  const mutualFriends = await redis.sinter('user:101:friends', 'user:102:friends'); // ['user:202', 'user:203']

  // 5. SORTED SETS (ZSET): Bảng xếp hạng Game thời gian thực
  await redis.zadd('leaderboard:racing', 1500, 'player_nam', 1820, 'player_tuan');
  // Lấy Top 10 người điểm cao nhất (từ cao xuống thấp)
  const topPlayers = await redis.zrevrange('leaderboard:racing', 0, 9, 'WITHSCORES');
}

