-- So sánh trực quan 4 chiến lược Caching Pattern

/*
1. CACHE-ASIDE (Phổ biến nhất):
   App ---> Kiểm tra Cache (Hit? Trả về)
    | (Miss)
    +---> Query Database ---> Ghi vào Cache ---> Trả về

2. WRITE-THROUGH (Nhất quán cao, ghi chậm):
   App ---> Ghi vào Cache ---> Đồng bộ ghi Database ---> Xong

3. WRITE-BACK / WRITE-BEHIND (Ghi siêu nhanh, rủi ro mất điện):
   App ---> Ghi vào Cache (Trả về ngay)
               | (Bất đồng bộ sau 5s)
               v
          Batch Ghi Database

4. CACHE INVALIDATION CHUẨN KHI UPDATE (Delete instead of Set):
*/
export async function updateUserProfile(userId: string, data: UpdateUserDto) {
  // Bước 1: Cập nhật dữ liệu vào Database chính (Single Source of Truth)
  await db.user.update({ where: { id: userId }, data });

  // Bước 2: BẮT BUỘC XÓA CACHE (Không nên tự tính toán để set lại cache)
  await redis.del(`user:profile:${userId}`);
}

