  // Bước 1: Cập nhật dữ liệu vào Database chính (Single Source of Truth)
  await db.user.update({ where: { id: userId }, data });

  // Bước 2: BẮT BUỘC XÓA CACHE (Không nên tự tính toán để set lại cache)
  await redis.del(`user:profile:${userId}`);
}

