// Cấu hình Connection Pool chuẩn sản xuất bằng thư viện pg (PostgreSQL) trong Node.js
import { Pool } from 'pg';

export const dbPool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,                       // Tối đa 20 kết nối đồng thời (được tái sử dụng liên tục)
  min: 5,                        // Luôn duy trì sẵn 5 kết nối nhàn rỗi trong bộ đệm
  idleTimeoutMillis: 30000,      // Đóng kết nối nhàn rỗi sau 30 giây
  connectionTimeoutMillis: 2000, // Nếu sau 2 giây không mượn được kết nối từ pool -> Ném lỗi Timeout ngay!
});

// Sử dụng Pool để thực thi truy vấn: Tự động mượn kết nối và trả về pool ngay khi xong
export async function executeQuery(text: string, params?: any[]) {
  const start = Date.now();
  // pool.query tự động: mượn client -> query -> giải phóng client về pool
  const res = await dbPool.query(text, params);
  const duration = Date.now() - start;

  if (duration > 1000) {
    console.warn(`Slow query detected (${duration}ms): ${text}`);
  }
  return res.rows;
}

