// Middleware định tuyến kết nối thông minh chống Replication Lag trong Node.js
import { Request, Response, NextFunction } from 'express';
import { primaryDb, replicaDb } from './database-pools';

export async function smartDbRouter(req: Request, res: Response, next: NextFunction) {
  const userId = req.user?.id;
  const lastWriteTimestamp = req.cookies[`last_write_${userId}`];

  // 1. Nếu là thao tác GHI (POST, PUT, DELETE) -> 100% dùng PRIMARY
  if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    req.db = primaryDb;
    // Đánh dấu thời điểm user vừa ghi dữ liệu
    res.cookie(`last_write_${userId}`, Date.now(), { maxAge: 5000 }); // Hiệu lực 5s
    return next();
  }

  // 2. Nếu là thao tác ĐỌC (GET):
  // Kiểm tra xem user này có vừa ghi dữ liệu trong vòng 5 giây trước không?
  const hasRecentWrite = lastWriteTimestamp && (Date.now() - parseInt(lastWriteTimestamp, 10)) < 5000;

  if (hasRecentWrite) {
    // ÉP BUỘC ĐỌC TỪ PRIMARY để chống hiện tượng Read-Your-Own-Writes do Replica Lag!
    req.db = primaryDb;
  } else {
    // An toàn: Đọc từ READ REPLICA để giảm tải cho Primary
    req.db = replicaDb;
  }

  return next();
}

