// Kết nối MongoDB Replica Set an toàn với Write Concern Majority (Node.js)
import { MongoClient } from 'mongodb';

// Chuỗi kết nối khai báo toàn bộ các thành viên trong Replica Set
const uri = "mongodb://db1.example.com:27017,db2.example.com:27017,db3.example.com:27017/my_app?replicaSet=rs0";

const client = new MongoClient(uri, {
  // 1. Write Concern: Đảm bảo ghi vào đa số node trước khi phản hồi (Chống mất dữ liệu)
  writeConcern: { w: 'majority', wtimeout: 5000 },

  // 2. Read Preference: Mặc định đọc từ Primary, hoặc đọc Secondary khi phân tích
  readPreference: 'primary' 
});

async function safeTransaction() {
  await client.connect();
  const db = client.db('my_app');

  // Giao dịch nhiều tài liệu (Multi-document Transaction) trên Replica Set
  const session = client.startSession();
  try {
    session.startTransaction({
      readConcern: { level: 'snapshot' },
      writeConcern: { w: 'majority' }
    });

    await db.collection('wallets').updateOne(
      { userId: 1 }, 
      { $inc: { balance: -100 } }, 
      { session }
    );

    await session.commitTransaction();
  } finally {
    await session.endSession();
  }
}

