-- Tự động cập nhật trường updated_at mỗi khi có câu lệnh UPDATE

CREATE OR REPLACE FUNCTION trigger_set_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW(); -- Tự động gán thời gian hiện tại
  RETURN NEW;
END;
