-- Tái hiện cạm bẫy Implicit Casting trong MySQL / PostgreSQL

-- Cấu trúc bảng: phone_number là VARCHAR(20) có Index B-tree
CREATE TABLE customers (
    id SERIAL PRIMARY KEY,
    phone_number VARCHAR(20) NOT NULL UNIQUE
);

-- ❌ TRUY VẤN LỖI HIỆU NĂNG (Implicit Cast): Truyền số nguyên thay vì chuỗi
-- Engine tự biến đổi thành: WHERE CAST(phone_number AS SIGNED) = 981234567
-- Query Plan: Full Table Scan (ALL), Index B-tree bị vứt bỏ hoàn toàn!
EXPLAIN SELECT * FROM customers WHERE phone_number = 0981234567;

-- ✅ TRUY VẤN CHUẨN MỰC (Đúng kiểu dữ liệu): Truyền chuỗi có dấu nháy đơn
-- Query Plan: Index Unique Scan / Const Seek siêu tốc trong 0.05ms!
EXPLAIN SELECT * FROM customers WHERE phone_number = '0981234567';

