// Triển khai Optimistic Locking chuẩn mực trong Node.js / TypeScript
import { db } from './database';

export async function updateArticleOptimistic(
  articleId: string, 
  newContent: string, 
  expectedVersion: number
): Promise<boolean> {
  // Thao tác Compare-And-Swap (CAS) nguyên tử
  const result = await db.article.updateMany({
    where: {
      id: articleId,
      version: expectedVersion // Chỉ update nếu version chưa bị ai khác thay đổi
    },
    data: {
      content: newContent,
      version: { increment: 1 } // Tự động tăng version lên 1 đơn vị
    }
  });

  // Nếu count === 0 nghĩa là đã có người khác cập nhật trước đó!
  if (result.count === 0) {
    throw new Error('Xung đột dữ liệu: Bài viết đã được chỉnh sửa bởi người khác. Vui lòng tải lại trang!');
  }

  return true;
}

