// Thiết kế lại an toàn bằng Transactional Outbox Pattern (TypeScript/Prisma)

export async function placeOrderSecurely(userId: string, totalAmount: number) {
  // BƯỚC 1: TRANSACTION CỰC NHANH (< 5ms), TUYỆT ĐỐI KHÔNG GỌI API MẠNG Ở ĐÂY!
  const order = await prisma.$transaction(async (tx) => {
    // 1. Tạo đơn hàng
    const newOrder = await tx.order.create({
      data: { userId, grandTotal: totalAmount, status: 'PENDING_PAYMENT' }
    });

    // 2. Ghi sự kiện vào bảng Outbox trong cùng transaction
    await tx.outboxEvent.create({
      data: {
        aggregateType: 'ORDER',
        aggregateId: newOrder.id,
        eventType: 'ORDER_CREATED_CHARGE_REQUESTED',
        payload: { orderId: newOrder.id, amount: totalAmount, userId },
        status: 'PENDING'
      }
    });

    return newOrder;
  }); // TRANSACTION KẾT THÚC VÀ GIẢI PHÓNG DB NGAY TỨC THÌ!

  return order;
}

// BƯỚC 2: BACKGROUND WORKER ĐỘC LẬP XỬ LÝ GỌI API BÊN NGOÀI
// File: workers/payment-processor.ts
export async function processOutboxPayments() {
  const pendingEvents = await prisma.outboxEvent.findMany({
    where: { status: 'PENDING' },
    take: 10
  });

  for (const event of pendingEvents) {
    try {
      // Gọi API bên thứ 3 thoải mái ở đây: Dù mất 10 giây cũng không ảnh hưởng DB chính!
      const paymentResponse = await callStripeApi(event.payload);

      await prisma.outboxEvent.update({
        where: { id: event.id },
        data: { status: 'PROCESSED', processedAt: new Date() }
      });
    } catch (error) {
      // Tự động Retry sau 5s, 10s...
      console.error('Lỗi cổng thanh toán, sẽ retry sau:', error);
    }
  }
}

