// 1. Ngôn ngữ truy vấn Cypher: Tìm đường đi rửa tiền vòng tròn (Fraud Ring Detection)
// Tìm các giao dịch chuyển tiền vòng quanh 3-5 tài khoản rồi quay lại chính chủ
MATCH path = (origin:Account)-[:TRANSFERRED*3..5]->(origin)
WHERE origin.is_flagged = true
RETURN path, length(path) AS hop_count
LIMIT 10;

// 2. Gợi ý bạn bè (Friends-of-Friends): Bạn của bạn nhưng chưa kết bạn với mình
MATCH (me:User {id: 'user_101'})-[:FRIEND]->(friend:User)-[:FRIEND]->(fof:User)
WHERE NOT (me)-[:FRIEND]->(fof) AND me <> fof
RETURN fof.name, COUNT(*) AS mutual_friends_count
ORDER BY mutual_friends_count DESC
LIMIT 5;

