-- Tạo Hypertable và cấu hình Tự động nén dữ liệu trong TimescaleDB (PostgreSQL)

-- 1. Tạo bảng đo đạc cảm biến thông thường
CREATE TABLE sensor_metrics (
    recorded_at TIMESTAMPTZ NOT NULL,
    device_id INT NOT NULL,
    temperature NUMERIC(5, 2) NOT NULL,
    humidity NUMERIC(5, 2) NOT NULL
);

-- 2. Biến thành Hypertable tự động cắt Chunks theo chu kỳ 1 ngày
SELECT create_hypertable('sensor_metrics', 'recorded_at', chunk_time_interval => INTERVAL '1 day');

-- 3. Kích hoạt chính sách Tự động Nén theo Cột (Columnar Compression):
-- Gom nhóm theo device_id, sắp xếp theo thời gian
ALTER TABLE sensor_metrics SET (
    timescaledb.compress,
    timescaledb.compress_segmentby = 'device_id',
    timescaledb.compress_orderby = 'recorded_at DESC'
);

-- Tự động nén tất cả các Chunks cũ hơn 7 ngày (Tiết kiệm 90% dung lượng đĩa!)
SELECT add_compression_policy('sensor_metrics', INTERVAL '7 days');

-- Tự động xóa sạch dữ liệu cũ hơn 1 năm (Data Retention Policy siêu tốc via DROP CHUNK)
SELECT add_retention_policy('sensor_metrics', INTERVAL '365 days');

