// Kiến trúc CDC Cache Invalidation Event Flow

/*
[ Backend App ] ---> 1. Ghi dữ liệu duy nhất vào DB (Không đụng tới Redis!)
      |
      v
[ PostgreSQL ] =====> 2. Ghi nhận commit thành công vào WAL File
      |
      | (Streaming binary WAL changes)
      v
[ Debezium Connector ] 
      |
      | 3. Sinh JSON Change Event: { before: {...}, after: {...}, op: "u" }
      v
[ Apache Kafka (Topic: dbserver1.public.users) ]
      |
      v
[ Cache Invalidation Worker (Consumer) ]
      |
      +---> 4. Trích xuất ID từ event payload -> Xóa key trên Redis:
               redis.unlink("user:profile:" + event.after.id);
*/

// Mã nguồn Consumer xử lý vô hiệu hóa Cache an toàn (Node.js/KafkaJS)
import { Kafka } from 'kafkajs';
import Redis from 'ioredis';

const kafka = new Kafka({ clientId: 'cache-invalidator', brokers: ['kafka:9092'] });
const consumer = kafka.consumer({ groupId: 'redis-invalidation-group' });
const redis = new Redis(process.env.REDIS_URL!);

export async function startCacheInvalidator() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'dbserver1.public.products', fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ message }) => {
      if (!message.value) return;
      const cdcPayload = JSON.parse(message.value.toString());

      // op: "c" (Create), "u" (Update), "d" (Delete)
      const productId = cdcPayload.after?.id || cdcPayload.before?.id;
      if (productId) {
        // Vô hiệu hóa Cache bất đồng bộ cực nhanh
        await redis.unlink(`cache:product:${productId}`);
        console.log(`[CDC Invalidation] Evicted cache for product ${productId}`);
      }
    }
  });
}

