// Thuật toán Định tuyến Shard bằng Virtual Buckets và Consistent Hashing trong Node.js
import crypto from 'node:crypto';

export class ShardRouter {
  private static readonly TOTAL_VIRTUAL_BUCKETS = 1024; // Cố định 1024 buckets ảo
  private bucketToNodeMap: Map<number, string>; // Ánh xạ bucket sang IP máy chủ database

  constructor() {
    this.bucketToNodeMap = new Map();
    // Ban đầu hệ thống có 4 nodes: Mỗi node quản lý 256 buckets
    // Node 0: Buckets 0..255
    // Node 1: Buckets 256..511
    // Node 2: Buckets 512..767
    // Node 3: Buckets 768..1023
    this.rebalanceBuckets(['db-shard-1', 'db-shard-2', 'db-shard-3', 'db-shard-4']);
  }

  // Lấy ra chuỗi kết nối Database chính xác cho một User cụ thể
  public getDatabaseNodeForUser(userId: string): string {
    // 1. Băm userId bằng MD5/Murmur3 để phân bổ đều tuyệt đối
    const hash = crypto.createHash('md5').update(userId).digest('hex');
    const hashInt = parseInt(hash.substring(0, 8), 16);

    // 2. Xác định Virtual Bucket (0 đến 1023)
    const bucketId = hashInt % ShardRouter.TOTAL_VIRTUAL_BUCKETS;

    // 3. Tra cứu máy chủ vật lý đang chịu trách nhiệm cho bucket đó
    return this.bucketToNodeMap.get(bucketId)!;
  }

  private rebalanceBuckets(nodes: string[]) {
    for (let i = 0; i < ShardRouter.TOTAL_VIRTUAL_BUCKETS; i++) {
      const assignedNode = nodes[i % nodes.length];
      this.bucketToNodeMap.set(i, assignedNode);
    }
  }
}

